sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        var body;
        if (method === 'GET') {
            body = getList(request.queryParams);
        } else if (method === 'POST') {
            body = createIncident(request.body.data);
        } else {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getList(qp) {
        var gr = new GlideRecord('x_2145749_qc_partner_incident');
        if (qp.partner) gr.addQuery('partner', qp.partner);
        if (qp.store) gr.addQuery('dark_store', qp.store);
        if (qp.severity) gr.addQuery('severity', qp.severity);
        gr.orderByDesc('sys_created_on');
        var limit = parseInt(qp.limit, 10) || 50;
        var offset = parseInt(qp.offset, 10) || 0;
        gr.chooseWindow(offset, offset + limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            results.push(toObj(gr));
        }
        return { success: true, result: results };
    }

    function createIncident(data) {
        if (!data || !data.partner || !data.incident_type) {
            return { success: false, error: 'partner and incident_type are required' };
        }
        var gr = new GlideRecord('x_2145749_qc_partner_incident');
        gr.initialize();
        gr.partner = data.partner;
        gr.dark_store = data.store || '';
        gr.incident_type = data.incident_type;
        gr.order_number = data.order_number || '';
        gr.description = data.description || '';
        gr.severity = data.severity || 'medium';
        gr.reported_by = data.reported_by || gs.getUserID();
        var sysId = gr.insert();
        if (!sysId) {
            return { success: false, error: 'Insert failed' };
        }
        gr.get(sysId);
        return { success: true, result: toObj(gr) };
    }

    function toObj(gr) {
        return {
            sys_id: gr.getUniqueValue(),
            partner: gr.partner.getDisplayValue(),
            store: gr.dark_store.getDisplayValue(),
            incident_type: gr.incident_type.toString(),
            order_number: gr.order_number.toString(),
            description: gr.description.toString(),
            severity: gr.severity.toString(),
            state: gr.state.toString(),
            created: gr.sys_created_on.toString()
        };
    }
})(request, response);
